conditions.leftValue:
={{ (() => {
  // The CSV this dashboard produces: tvm-overdue-<date from the dashboard name>.csv
  const dashboard = $("Split out files").item.json;
  const csvName = "tvm-overdue-" + dashboard.name.slice(15, 25) + ".csv";
  const csv = $("List CSVs already uploaded").all()
    .flatMap(page => page.json.value ?? [])
    .find(file => file.name === csvName);
  // Needed when the CSV is missing, or the dashboard was re-uploaded after the CSV was made
  return !csv || DateTime.fromISO(dashboard.lastModifiedDateTime) > DateTime.fromISO(csv.lastModifiedDateTime);
})() }}

parameters.jsCode:
// Turns each downloaded SLA_Flow_Stock dashboard into the text of tvm-overdue-YYYY-MM-DD.csv.
//
// The dashboard repeats every ticket once per team and per owner, so only the "All teams"
// copy is read: the Active Tickets table and the Ready for Validation & Pending/PER table.
// If the layout changes (a table is missing, a row doesn't have 11 cells, or the number of
// rows doesn't match the table's own "All active (N)" total), this step fails instead of
// uploading a wrong CSV.

const TABLES = [
  { id: 'scope-all-active-table', key: 'active' },
  { id: 'scope-all-held-active-table', key: 'readyOrPending' },
];

// Column names and order of the CSV, matching the existing TVM Tickets sheet
const HEADER = [
  'Overdue Tickets', 'Ticket URL', 'Severity', 'State', 'Status', 'Assignment Group',
  'Assignment', 'Created', 'Days Actual', 'SLA Days', 'Days Over', 'Summary', 'UploadDate',
];

const SEVERITY_ORDER = { critical: 0, high: 1, medium: 2, low: 3 };

const NAMED_ENTITIES = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', mdash: '—', ndash: '–',
  hellip: '…', lsquo: '‘', rsquo: '’', ldquo: '“', rdquo: '”', bull: '•',
};

// Turns HTML codes like &amp; and &#x27; back into the characters they stand for
const decodeEntities = (text) =>
  text.replace(/&(#[0-9]+|#x[0-9a-f]+|[a-z]+);/gi, (match, entity) => {
    if (entity[0] === '#') {
      const isHex = entity[1].toLowerCase() === 'x';
      const code = parseInt(entity.slice(isHex ? 2 : 1), isHex ? 16 : 10);
      return code > 0 && code <= 0x10ffff ? String.fromCodePoint(code) : match;
    }
    return NAMED_ENTITIES[entity.toLowerCase()] ?? match;
  });

// A table cell as plain text: tags removed, codes decoded, whitespace squeezed to single spaces
const cellText = (html) =>
  decodeEntities(html.replace(/<[^>]*>/g, ''))
    .replace(/\s+/g, ' ')
    .trim();

// The description box as plain text, keeping its line breaks
const descriptionText = (html) => {
  const box = html.match(/<div[^>]*class="[^"]*desc-box[^"]*"[^>]*>([\s\S]*)<\/div>/);
  const inner = box ? box[1] : html;
  return decodeEntities(inner.replace(/<br\s*\/?>/gi, '\n').replace(/<[^>]*>/g, ''))
    .replace(/\r\n?/g, '\n')
    .trim();
};

// Lower case with single spaces, so the people list can be typed loosely
const normalizeName = (name) => String(name).replace(/\s+/g, ' ').trim().toLowerCase();

// Quotes a CSV field when it holds a comma, a quote or a line break
const csvField = (value) => {
  const text = String(value ?? '');
  return /[",\r\n]/.test(text) ? '"' + text.replace(/"/g, '""') + '"' : text;
};

// Reads one ticket table and checks it against the total the dashboard states for it
const readTable = (html, id, fileName) => {
  const layoutError = (problem) =>
    new Error('Dashboard layout changed: ' + problem + ' (' + fileName + ')');

  const start = html.search(new RegExp('<table[^>]*\\bid="' + id + '"'));
  if (start === -1) throw layoutError('table "' + id + '" not found');
  const end = html.indexOf('</table>', start);
  const table = html.slice(start, end === -1 ? html.length : end);

  // The table's Show filter, e.g. <option value="all" ...>All active (277)</option>
  const filterId = id.replace(/-table$/, '-filter');
  const select = html.match(new RegExp('<select[^>]*\\bid="' + filterId + '"[^>]*>([\\s\\S]*?)</select>'));
  const total = select && select[1].match(/<option[^>]*value="all"[^>]*>[^<]*\((\d+)\)/);
  if (!total) throw layoutError('the ticket total for "' + id + '" was not found');

  const tickets = [];
  for (const row of table.matchAll(/<tr\b[^>]*\bdata-status="[^"]*"[^>]*>([\s\S]*?)<\/tr>/g)) {
    const cells = [...row[1].matchAll(/<td\b[^>]*>([\s\S]*?)<\/td>/g)].map((cell) => cell[1]);
    if (cells.length !== 11) {
      throw layoutError('a ticket row in "' + id + '" has ' + cells.length + ' cells instead of 11');
    }
    const link = cells[0].match(/<a\b[^>]*\bhref="([^"]*)"[^>]*>([\s\S]*?)<\/a>/);
    if (!link) throw layoutError('a ticket row in "' + id + '" has no ticket link');
    tickets.push({
      number: cellText(link[2]),
      url: decodeEntities(link[1]),
      summary: descriptionText(cells[1]),
      severity: cellText(cells[2]),
      state: cellText(cells[3]),
      status: cellText(cells[4]),
      group: cellText(cells[5]),
      assignedTo: cellText(cells[6]),
      created: cellText(cells[7]),
      daysActual: cellText(cells[8]),
      slaDays: cellText(cells[9]),
      daysOver: cellText(cells[10]),
    });
  }

  if (tickets.length !== Number(total[1])) {
    throw layoutError('"' + id + '" lists ' + total[1] + ' tickets but ' + tickets.length + ' rows were read');
  }
  return tickets;
};

// The people whose tickets go in the CSV, keyed by their loosely typed name
const people = $('Set SharePoint host and people').first().json.people;
const listed = (Array.isArray(people) ? people : []).map((name) => String(name).trim()).filter(Boolean);
if (listed.length === 0) {
  throw new Error('No people listed. Add at least one name to "people" in the "Set SharePoint host and people" step.');
}
const wanted = new Map(listed.map((name) => [normalizeName(name), name]));

const severityRank = (severity) => SEVERITY_ORDER[severity.toLowerCase()] ?? 4;

const results = [];
const inputs = $input.all();
for (let index = 0; index < inputs.length; index++) {
  // The dashboard this download came from, for its file name and date
  const dashboard = $('Keep dashboards needing a CSV').itemMatching(index).json;
  const dateMatch = /^SLA_Flow_Stock_(\d{4}-\d{2}-\d{2})\.html$/.exec(dashboard.name);
  if (!dateMatch) throw new Error('Unexpected dashboard file name: ' + dashboard.name);
  const uploadDate = dateMatch[1];

  const html = (await this.helpers.getBinaryDataBuffer(index, 'data')).toString('utf8');

  const counts = {};
  const tickets = [];
  for (const table of TABLES) {
    const rows = readTable(html, table.id, dashboard.name);
    counts[table.key] = rows.length;
    tickets.push(...rows);
  }

  // Keep the selected people's tickets: by person, then Critical to Low, then oldest first.
  // Ties keep the dashboard's order (Active before Ready for Validation & Pending/PER).
  const kept = tickets
    .filter((ticket) => wanted.has(normalizeName(ticket.assignedTo)))
    .sort(
      (a, b) =>
        a.assignedTo.localeCompare(b.assignedTo) ||
        severityRank(a.severity) - severityRank(b.severity) ||
        Number(b.daysActual) - Number(a.daysActual),
    );

  const lines = [HEADER].concat(
    kept.map((ticket) => [
      ticket.number, ticket.url, ticket.severity, ticket.state, ticket.status, ticket.group,
      ticket.assignedTo, ticket.created, ticket.daysActual, ticket.slaDays, ticket.daysOver,
      ticket.summary, uploadDate,
    ]),
  );
  const csv = lines.map((values) => values.map(csvField).join(',')).join('\r\n') + '\r\n';

  const namesWithTickets = new Set(kept.map((ticket) => normalizeName(ticket.assignedTo)));
  const peopleWithoutTickets = [...wanted]
    .filter(([key]) => !namesWithTickets.has(key))
    .map(([, name]) => name);

  results.push({
    json: {
      fileName: 'tvm-overdue-' + uploadDate + '.csv',
      dashboard: dashboard.name,
      uploadDate,
      dashboardTickets: counts,
      ticketsWritten: kept.length,
      peopleWithoutTickets,
      csv,
    },
    pairedItem: { item: index },
  });
}

return results;

parameters.fileName:
={{ (() => {
  // csvFolderPath, URL-encoded part by part, then the CSV's name: Parent Folder is "root"
  const parts = String($("Set SharePoint host and people").first().json.csvFolderPath ?? "")
    .split(/[\\/]/)
    .map(part => part.trim())
    .filter(Boolean);
  return [...parts.map(encodeURIComponent), $("Extract tickets to CSV text").item.json.fileName].join("/");
})() }}

assignments.value:
={{ (() => {
  // A failed step reports under "execution"; a failed schedule trigger reports under "trigger"
  const failure = $("On workflow error").item.json;
  const error = failure.execution?.error ?? failure.trigger?.error ?? {};
  const blocks = [
    {
      type: "TextBlock",
      text: failure.workflow.name + " failed",
      weight: "Bolder",
      wrap: true
    },
    {
      type: "TextBlock",
      text: "Step: " + (failure.execution?.lastNodeExecuted ?? "schedule trigger"),
      wrap: true,
      spacing: "Small"
    },
    {
      type: "TextBlock",
      text: "Error: " + (error.message ?? "no error message"),
      wrap: true,
      spacing: "None"
    }
  ];
  // Some errors carry extra detail, such as SharePoint's own explanation
  if (error.description) {
    blocks.push({
      type: "TextBlock",
      text: "Details: " + error.description,
      wrap: true,
      spacing: "None"
    });
  }
  // Button to the failed run, when there is one
  const actions = failure.execution?.url
    ? [
        {
          type: "Action.OpenUrl",
          title: "Open the failed run",
          url: failure.execution.url
        }
      ]
    : [];
  // Teams Workflows webhooks expect an Adaptive Card wrapped in a message
  return {
    type: "message",
    attachments: [
      {
        contentType: "application/vnd.microsoft.card.adaptive",
        contentUrl: null,
        content: {
          "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
          type: "AdaptiveCard",
          version: "1.4",
          body: blocks,
          actions: actions
        }
      }
    ]
  };
})() }}
